    // ===============================================================
    std::cout << "\n===================================================" << std::endl;
    std::cout << "FASE 3A: Gerando rTalesHash.txt (Todos os arquivos)..." << std::endl;
    std::ofstream allHashFile("rTalesHash.txt");
