```dart
/// Converte uma posição 3D para um Offset 2D, assumindo que a matriz 'transform'
/// já é a matriz MVP (Model-View-Projection) final.
Offset convertPositionTo2D(
    Vector3 position, Matrix4 transform, double screenWidth, double screenHeight) {
  // 1. Define a posição 3D. Se for uma posição de objeto, mantenha Z,
  // mas se for um ponto arbitrário fora da cena, use um Z consistente.
  // Como você está testando um ponto genérico, vamos usá-lo diretamente.
  Vector4 worldPosition = Vector4(position.x, position.y, position.z, 1.0);

  // 2. Aplica a transformação MVP (Resultado em Clip Space)
  Vector4 clipPosition = transform.transformed(worldPosition);

  // Se W for zero ou muito perto de zero, o ponto está no plano de projeção
  // infinito ou é inválido, evitando divisão por zero.
  if (clipPosition.w.abs() < 0.001) {
    return Offset(double.infinity, double.infinity);
  }

  // 3. Divisão de Perspectiva (Clip Space -> NDC)
  double ndcX = clipPosition.x / clipPosition.w;
  double ndcY = clipPosition.y / clipPosition.w;

  // 4. Mapeamento para Tela (NDC [-1, 1] -> Screen [0, Width/Height])
  // Formula: (ndc_value + 1) / 2 * screen_dimension
  double x2D = (ndcX + 1.0) / 2.0 * screenWidth;
  double y2D = (ndcY + 1.0) / 2.0 * screenHeight;

  // Retorna as coordenadas 2D como um Offset
  return Offset(x2D, y2D);
}
```

